namespace Knx.App.Localization;

public static class AddressAssignmentStrings
{
    public static IReadOnlyList<string> Languages => SecureConnectionStrings.Languages;
    public static IReadOnlyCollection<string> Keys => Text.Keys;
    public static string Get(string key) => GetForLanguage(Strings.Language, key);
    public static string GetForLanguage(string language, string key)
    {
        var index = Languages.ToList().IndexOf(language);
        key = key switch { "InvalidSelection" => "Invalid", "UnsupportedSecureProvisioning" => "SecureBlocked", "PhysicalBindingRequired" => "NeedPhysical", "AmbiguousResponse" => "Ambiguous", "TargetResponded" => "Conflict", "ReservationRequired" => "NeedConfirm", "StaleReview" => "Stale", "TransportFailed" => "Failed", "RecoveryRequired" => "Unresolved", "Disposed" => "Cancelled", "Idle" => "Scope", _ => key };
        return (Text.TryGetValue(key, out var values) ? values : Text["Failed"])[index < 0 ? 1 : index];
    }
